package policy

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// Decision is the variant a Rule returns. Allowed proceeds; RequiresApproval
// routes to a human; Denied stops the action with a reason.
type Decision interface{ isDecision() }

type Allowed struct{}

func (Allowed) isDecision() {}

type RequiresApproval struct {
	ToUser string
	TTL    time.Duration
}

func (RequiresApproval) isDecision() {}

type Denied struct {
	Reason string
}

func (Denied) isDecision() {}

// Rule is the function type registered per action. ctx is passed through so
// rules can timeout or call out to async stores; attrs carries action-specific
// attributes (workload, env, region, …).
type Rule = func(context.Context, map[string]string) Decision

// registryState holds the per-action rule table behind a mutex. Held
// behind a reference so builder-style chaining shares state.
type registryState struct {
	mu    sync.Mutex
	rules map[string]Rule
}

// Registry is the policy lookup table. Build via New + Register; pass to
// Check.
type Registry struct {
	state *registryState
}

// New creates an empty Registry. Until at least one Register call, every
// Check returns Denied — fail-closed is the only safe default for an
// approval gate.
func New() Registry {
	s := registryState{rules: map[string]Rule{}}
	return Registry{state: &s}
}

// Register attaches a Rule to an action name. Later Register calls for the
// same action replace the previous rule.
func Register(r Registry, action string, rule Rule) Registry {
	r.state.mu.Lock()
	defer r.state.mu.Unlock()
	r.state.rules[action] = rule
	return r
}

// Check evaluates the rule for action against attrs. If no rule is
// registered, returns Denied with an explanatory reason — fail closed.
func Check(r Registry, ctx context.Context, action string, attrs map[string]string) Decision {
	r.state.mu.Lock()
	rule, ok := r.state.rules[action]
	r.state.mu.Unlock()
	if !ok {
		return Denied{Reason: fmt.Sprintf("no policy registered for %v", action)}
	}
	return rule(ctx, attrs)
}

// AllowAll is a convenience rule that returns Allowed regardless of input.
// Useful in tests or when you want to register a placeholder rule.
func AllowAll(ctx context.Context, attrs map[string]string) Decision {
	return Allowed{}
}

// DenyAll is a convenience rule that always returns Denied with the given
// reason. Useful for explicit "do not run" registrations.
func DenyAll(reason string) Rule {
	return func(ctx context.Context, attrs map[string]string) Decision {
		return Denied{Reason: reason}
	}
}
